// One-hot encoded counter. Translates to a 10-bit binary counter with a
// period of 1000 clock cycles, as described in the prompt. Active high
// reset, synchronous to the clock.
module TopModule(input clk, input reset, output reg [9:0] q);
    reg [2:0] counter;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            q <= 10'b0000000001;
        end else begin
            case (counter)
                0: q <= 10'b0000000001;
                1: q <= 10'b0000000010;
                2: q <= 10'b0000000100;
                3: q <= 10'b0000001000;
                4: q <= 10'b0000010000;
                5: q <= 10'b0000100000;
                6: q <= 10'b0001000000;
                7: q <= 10'b0010000000;
                8: q <= 10'b0100000000;
                9: q <= 10'b1000000000;
                default: q <= 10'b0000000001;
            endcase
            counter <= counter + 1;
            if (counter == 9) counter <= 0;
        end
    end
endmodule

